import 'package:flutter/material.dart';
import '../services/ecg_simulator.dart';

/// Animated prototype ECG waveform. Mirrors the canvas-based
/// implementation in the web prototype (EcgWaveform.tsx): a rolling
/// buffer of samples generated by ecg_simulator.dart, redrawn on every
/// animation tick via CustomPainter. Demonstration only -- not a
/// clinically diagnostic signal.
class EcgWaveformWidget extends StatefulWidget {
  final bool running;
  final double bpm;
  final bool abnormal;
  final double height;
  final Color lineColor;
  final int resetSignal;

  const EcgWaveformWidget({
    super.key,
    required this.running,
    required this.bpm,
    required this.abnormal,
    this.height = 160,
    this.lineColor = const Color(0xFF16A34A),
    this.resetSignal = 0,
  });

  @override
  State<EcgWaveformWidget> createState() => _EcgWaveformWidgetState();
}

class _EcgWaveformWidgetState extends State<EcgWaveformWidget> with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  final List<double> _buffer = [];
  EcgGeneratorState _state = EcgGeneratorState();
  Duration _lastTick = Duration.zero;
  static const int _maxPoints = 220;
  static const double _sampleRate = 60; // samples per second

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this, duration: const Duration(days: 1))
      ..addListener(_onTick)
      ..repeat();
  }

  @override
  void didUpdateWidget(covariant EcgWaveformWidget oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.resetSignal != widget.resetSignal) {
      _buffer.clear();
      _state = EcgGeneratorState();
    }
  }

  void _onTick() {
    if (!widget.running) {
      _lastTick = _controller.lastElapsedDuration ?? _lastTick;
      return;
    }
    final now = _controller.lastElapsedDuration ?? Duration.zero;
    var dtMs = (now - _lastTick).inMilliseconds;
    _lastTick = now;
    if (dtMs <= 0) return;
    if (dtMs > 200) dtMs = 200; // clamp to avoid a huge jump after a frame drop
    final dt = dtMs / 1000.0;

    final samplesToAdd = (dt * _sampleRate).round().clamp(1, 20);
    const stepDt = 1 / _sampleRate;
    for (var i = 0; i < samplesToAdd; i++) {
      _buffer.add(nextEcgSample(_state, stepDt, widget.bpm, widget.abnormal));
    }
    while (_buffer.length > _maxPoints) {
      _buffer.removeAt(0);
    }
    setState(() {});
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(12),
      child: SizedBox(
        width: double.infinity,
        height: widget.height,
        child: CustomPaint(
          painter: _EcgPainter(samples: List.of(_buffer), color: widget.lineColor),
        ),
      ),
    );
  }
}

class _EcgPainter extends CustomPainter {
  final List<double> samples;
  final Color color;

  _EcgPainter({required this.samples, required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final bgPaint = Paint()..color = const Color(0xFFFBFDFF);
    canvas.drawRect(Offset.zero & size, bgPaint);

    final gridPaint = Paint()
      ..color = const Color(0x2E94A3B8)
      ..strokeWidth = 1;
    const gridSize = 20.0;
    for (double x = 0; x < size.width; x += gridSize) {
      canvas.drawLine(Offset(x, 0), Offset(x, size.height), gridPaint);
    }
    for (double y = 0; y < size.height; y += gridSize) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y), gridPaint);
    }

    if (samples.length < 2) return;

    final linePaint = Paint()
      ..color = color
      ..strokeWidth = 2
      ..style = PaintingStyle.stroke
      ..strokeJoin = StrokeJoin.round
      ..strokeCap = StrokeCap.round;

    final path = Path();
    final midY = size.height / 2;
    final amp = size.height * 0.35;
    final stepX = size.width / (samples.length - 1);

    for (var i = 0; i < samples.length; i++) {
      final x = i * stepX;
      final y = midY - samples[i] * amp;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    canvas.drawPath(path, linePaint);
  }

  @override
  bool shouldRepaint(covariant _EcgPainter oldDelegate) => true;
}
